// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {BitMaps} from "@openzeppelin/contracts/utils/structs/BitMaps.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {ILiquidityPool} from "./interfaces/ILiquidityPool.sol";
import {IRepayer} from "./interfaces/IRepayer.sol";
import {IWrappedNativeToken} from "./interfaces/IWrappedNativeToken.sol";

import {InputOutputTokenData} from "./utils/AdapterHelper.sol";
import {CCTPV2Adapter} from "./utils/CCTPV2Adapter.sol";
import {AcrossAdapter} from "./utils/AcrossAdapter.sol";
import {StargateAdapter} from "./utils/StargateAdapter.sol";
import {SuperchainStandardBridgeAdapter} from "./utils/SuperchainStandardBridgeAdapter.sol";
import {ArbitrumGatewayAdapter} from "./utils/ArbitrumGatewayAdapter.sol";
import {GnosisOmnibridgeAdapter} from "./utils/GnosisOmnibridgeAdapter.sol";
import {USDT0Adapter} from "./utils/USDT0Adapter.sol";
import {PolygonPosBridgeAdapter} from "./utils/PolygonPosBridgeAdapter.sol";
import {ERC7201Helper} from "./utils/ERC7201Helper.sol";
import {HelperLib} from "./utils/HelperLib.sol";

/// @title Performs repayment to Liquidity Pools on same/different chains.
/// Routes, which is a destination pool/domain and a bridging provider, have to be approved by admin.
/// REPAYER_ROLE is needed to finalize/init rebalancing process.
/// @notice Upgradeable.
/// @author Tanya Bushenyova <tanya@chainsafe.io>
contract Repayer is
    IRepayer,
    AccessControlUpgradeable,
    CCTPV2Adapter,
    AcrossAdapter,
    StargateAdapter,
    SuperchainStandardBridgeAdapter,
    ArbitrumGatewayAdapter,
    GnosisOmnibridgeAdapter,
    USDT0Adapter,
    PolygonPosBridgeAdapter
{
    using SafeERC20 for IERC20;
    using BitMaps for BitMaps.BitMap;
    using EnumerableSet for EnumerableSet.AddressSet;

    Domain immutable public DOMAIN;
    bytes32 constant internal REPAYER_ROLE = "REPAYER_ROLE";
    bytes32 constant internal SET_TOKENS_ROLE = "SET_TOKENS_ROLE";
    IWrappedNativeToken immutable public WRAPPED_NATIVE_TOKEN;

    /// @custom:storage-location erc7201:sprinter.storage.Repayer
    struct RepayerStorage {
        mapping(address pool => BitMaps.BitMap) allowedRoutes;
        EnumerableSet.AddressSet knownPools;
        mapping(address pool => bool) poolSupportsAllTokens; // Deprecated.
        mapping(address inputToken =>
            mapping(bytes32 outputToken => InputOutputTokenData)) inputOutputTokens;
        mapping(address pool => IERC20 token) poolOnlySupportsToken;
    }

    bytes32 private constant STORAGE_LOCATION = 0xa6615d19cc0b2a17ee46271ca76cd3f303efb9bf682e7eb5c4e7290e895cde00;

    event SetRoute(
        address destinationPool,
        Domain destinationDomain,
        Provider provider,
        IERC20 onlySupportedToken,
        bool isAllowed
    );
    event InitiateRepay(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        Provider provider
    );
    event ProcessRepay(IERC20 token, uint256 amount, address destinationPool, Provider provider);
    event SetInputOutputToken(
        address inputToken,
        Domain destinationDomain,
        bytes32 outputToken,
        int8 localDecimalsGreaterBy,
        bool isAllowed
    );

    error ZeroAmount();
    error RouteDenied();
    error UnsupportedProvider();
    error InvalidPoolAssets();

    struct DestinationToken {
        Domain destinationDomain;
        bytes32 outputToken;
        int8 localDecimalsGreaterBy;
    }

    struct InputOutputToken {
        address inputToken;
        DestinationToken[] destinationTokens;
    }

    constructor(
        Domain localDomain,
        IERC20 usdc,
        address acrossSpokePool,
        address wrappedNativeToken,
        address stargateTreasurer,
        address optimismBridge,
        address baseBridge,
        address arbitrumGatewayRouter,
        address omnibridge,
        address gnosisUsdcxdai,
        address gnosisUsdceSwap,
        address ethereumAmb,
        address usdt0Oft,
        address usdt0FeeNativeToken,
        address cctpV2TokenMessenger,
        address cctpV2MessageTransmitter,
        address polygonPosRootChainManager
    )
        CCTPV2Adapter(
            usdc,
            cctpV2TokenMessenger,
            cctpV2MessageTransmitter
        )
        AcrossAdapter(acrossSpokePool)
        StargateAdapter(stargateTreasurer)
        SuperchainStandardBridgeAdapter(optimismBridge, baseBridge, wrappedNativeToken, address(usdc))
        ArbitrumGatewayAdapter(arbitrumGatewayRouter)
        GnosisOmnibridgeAdapter(
            localDomain,
            omnibridge,
            address(usdc),
            gnosisUsdcxdai,
            gnosisUsdceSwap,
            ethereumAmb
        )
        USDT0Adapter(usdt0Oft, usdt0FeeNativeToken)
        PolygonPosBridgeAdapter(polygonPosRootChainManager)
    {
        ERC7201Helper.validateStorageLocation(
            STORAGE_LOCATION,
            "sprinter.storage.Repayer"
        );
        DOMAIN = localDomain;
        WRAPPED_NATIVE_TOKEN = IWrappedNativeToken(wrappedNativeToken);
        _disableInitializers();
    }

    receive() external payable {
        // Allow native token transfers.
    }

    function initialize(
        address admin,
        address repayer,
        address setTokens,
        address[] calldata pools,
        Domain[] calldata domains,
        Provider[] calldata providers,
        IERC20[] calldata poolOnlySupportsToken,
        InputOutputToken[] calldata inputOutputTokens
    ) external initializer() {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REPAYER_ROLE, repayer);
        _grantRole(SET_TOKENS_ROLE, setTokens);
        _setRoute(pools, domains, providers, poolOnlySupportsToken, true);
        _setInputOutputTokens(inputOutputTokens, true);
    }

    function setRoute(
        address[] calldata pools,
        Domain[] calldata domains,
        Provider[] calldata providers,
        IERC20[] calldata poolOnlySupportsToken,
        bool isAllowed
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setRoute(pools, domains, providers, poolOnlySupportsToken, isAllowed);
    }

    function setInputOutputTokens(
        InputOutputToken[] calldata inputOutputTokens,
        bool isAllowed
    ) external onlyRole(SET_TOKENS_ROLE) {
        _setInputOutputTokens(inputOutputTokens, isAllowed);
    }

    /// @notice If the selected provider requires native currency payment to cover fees,
    /// then caller has to include it in the transaction. It is then the responsibility
    /// of the Adapter to forward the payment and return any change back to the caller.
    /// @dev Adapters are responsible for revoking unused allowance if necessary.
    function initiateRepay(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        Provider provider,
        bytes calldata extraData
    ) external payable override onlyRole(REPAYER_ROLE) {
        require(amount > 0, ZeroAmount());
        if (token == WRAPPED_NATIVE_TOKEN) {
            uint256 thisBalance = address(this).balance - msg.value;
            if (thisBalance > 0) WRAPPED_NATIVE_TOKEN.deposit{value: thisBalance}();
        }

        require(HelperLib.balanceOfThis(token) >= amount, InsufficientBalance());
        require(isRouteAllowed(destinationPool, destinationDomain, provider), RouteDenied());

        emit InitiateRepay(token, amount, destinationPool, destinationDomain, provider);

        RepayerStorage storage $ = _getStorage();

        IERC20 onlySupportedToken = $.poolOnlySupportsToken[destinationPool];
        if (onlySupportedToken != IERC20(address(0))) {
            require(token == onlySupportedToken, InvalidToken());
        }

        if (provider == Provider.LOCAL) {
            require(destinationPool != address(this), RouteDenied());
            require(destinationDomain == DOMAIN, UnsupportedDomain());
            // For local we proceed to the process right away.
            _processRepayLOCAL(token, amount, destinationPool);
        } else
        if (provider == Provider.CCTP_V2) {
            initiateTransferCCTPV2(token, amount, destinationPool, destinationDomain);
        } else
        if (provider == Provider.ACROSS) {
            initiateTransferAcross(
                token,
                amount,
                destinationPool,
                destinationDomain,
                extraData,
                $.inputOutputTokens[address(token)]
            );
        } else
        if (provider == Provider.STARGATE) {
            initiateTransferStargate(token, amount, destinationPool, destinationDomain, extraData, _msgSender());
        } else
        if (provider == Provider.SUPERCHAIN_STANDARD_BRIDGE) {
            initiateTransferSuperchainStandardBridge(
                token,
                amount,
                destinationPool,
                destinationDomain,
                extraData,
                DOMAIN,
                $.inputOutputTokens[address(token)]
            );
        } else 
        if (provider == Provider.ARBITRUM_GATEWAY) {
            initiateTransferArbitrum(
                token,
                amount,
                destinationPool,
                destinationDomain,
                extraData,
                DOMAIN,
                $.inputOutputTokens[address(token)]
            );
        } else
        if (provider == Provider.GNOSIS_OMNIBRIDGE) {
            // When bridging USDC to Gnosis, we must bridge to self to swap USDCxDAI on Gnosis through process().
            // It is the Repayment Service responsibility to specify Repayer itself as destination explicitly.
            initiateTransferGnosisOmnibridge(token, amount, destinationPool, destinationDomain, DOMAIN);
        } else
        if (provider == Provider.USDT0) {
            initiateTransferUSDT0(token, amount, destinationPool, destinationDomain, extraData, _msgSender());
        } else
        if (provider == Provider.POLYGON_POS_BRIDGE) {
            // When bridging from Polygon, the PoS exit releases the tokens to the burner, so they
            // must come back to the Repayer itself and be forwarded through process().
            initiateTransferPolygonPosBridge(
                token,
                amount,
                destinationPool,
                destinationDomain,
                extraData,
                DOMAIN,
                $.inputOutputTokens[address(token)]
            );
        } else {
            revert UnsupportedProvider();
        }
    }

    function processRepay(
        address destinationPool,
        Provider provider,
        bytes calldata extraData
    ) external override onlyRole(REPAYER_ROLE) {
        require(isRouteAllowed(destinationPool, DOMAIN, Provider.LOCAL), RouteDenied());
        IERC20 token;
        uint256 amount = 0;
        bool processedToThis = false;
        if (provider == Provider.CCTP_V2) {
            (token, amount) = processTransferCCTPV2(destinationPool, extraData);
        } else
        if (provider == Provider.GNOSIS_OMNIBRIDGE) {
            (token, amount) = processTransferGnosisOmnibridge(address(this), DOMAIN, extraData);
            processedToThis = true;
        } else
        if (provider == Provider.POLYGON_POS_BRIDGE) {
            (token, amount) = processTransferPolygonPosBridge(extraData);
            processedToThis = true;
        } else {
            revert UnsupportedProvider();
        }
        if (processedToThis && destinationPool != address(this)) {
            token.safeTransfer(destinationPool, amount);
        }
        IERC20 onlySupportedToken = _getStorage().poolOnlySupportsToken[destinationPool];
        if (onlySupportedToken != IERC20(address(0))) {
            require(token == onlySupportedToken, InvalidToken());
        }

        emit ProcessRepay(token, amount, destinationPool, provider);
    }

    function _processRepayLOCAL(
        IERC20 token,
        uint256 amount,
        address destinationPool
    ) internal {
        token.safeTransfer(destinationPool, amount);
        emit ProcessRepay(token, amount, destinationPool, Provider.LOCAL);
    }

    function _setRoute(
        address[] calldata pools,
        Domain[] calldata domains,
        Provider[] calldata providers,
        IERC20[] calldata poolOnlySupportsToken,
        bool isAllowed
    ) internal {
        RepayerStorage storage $ = _getStorage();
        require(pools.length == domains.length, InvalidLength());
        require(pools.length == providers.length, InvalidLength());
        require(pools.length == poolOnlySupportsToken.length, InvalidLength());
        for (uint256 i = 0; i < pools.length; ++i) {
            address pool = pools[i];
            Domain domain = domains[i];
            Provider provider = providers[i];
            IERC20 onlySupportedToken = poolOnlySupportsToken[i];
            require(pool != address(0), ZeroAddress());
            if (domain == DOMAIN) {
                require(provider == Provider.LOCAL, UnsupportedProvider());
                if (onlySupportedToken != IERC20(address(0))) {
                    require(ILiquidityPool(pool).ASSETS() == onlySupportedToken, InvalidPoolAssets());
                }
            } else {
                require(provider != Provider.LOCAL, UnsupportedProvider());
            }
            $.allowedRoutes[pool].setTo(_toIndex(domain, provider), isAllowed);
            if (isAllowed) {
                $.knownPools.add(pool);
            }
            $.poolOnlySupportsToken[pool] = onlySupportedToken;
            emit SetRoute(pool, domain, provider, onlySupportedToken, isAllowed);
        }
    }

    function _setInputOutputTokens(
        InputOutputToken[] calldata inputOutputTokens,
        bool isAllowed
    ) internal {
        RepayerStorage storage $ = _getStorage();
        for (uint256 i = 0; i < inputOutputTokens.length; ++i) {
            address inputToken = inputOutputTokens[i].inputToken;
            DestinationToken[] calldata destinationTokens = inputOutputTokens[i].destinationTokens;
            for (uint256 j = 0; j < destinationTokens.length; ++j) {
                DestinationToken calldata destinationToken = destinationTokens[j];
                Domain destinationDomain = destinationToken.destinationDomain;
                bytes32 outputToken = destinationToken.outputToken;
                int8 localDecimalsGreaterBy = destinationToken.localDecimalsGreaterBy;
                require(destinationDomain != DOMAIN, UnsupportedDomain());
                InputOutputTokenData storage inputOutputTokenData = $.inputOutputTokens[inputToken][outputToken];
                inputOutputTokenData.destinationDomains.setTo(uint256(destinationDomain), isAllowed);
                inputOutputTokenData.localDecimalsGreaterBy[destinationDomain] = localDecimalsGreaterBy;
                emit SetInputOutputToken(
                    inputToken,
                    destinationDomain,
                    outputToken,
                    localDecimalsGreaterBy,
                    isAllowed
                );
            }
        }
    }

    function getAllRoutes()
        external view returns (
            address[] memory pools,
            Domain[] memory domains,
            Provider[] memory providers,
            IERC20[] memory poolOnlySupportsToken
        ) 
    {
        RepayerStorage storage $ = _getStorage();
        uint256 totalPools = $.knownPools.length();
        uint256 totalDomains = uint256(type(Domain).max) + 1;
        uint256 totalProviders = uint256(type(Provider).max) + 1;
        uint256 totalRoutes = totalPools * totalDomains * totalProviders;
        pools = new address[](totalRoutes);
        domains = new Domain[](totalRoutes);
        providers = new Provider[](totalRoutes);
        poolOnlySupportsToken = new IERC20[](totalRoutes);
        uint256 resultLength = 0;
        for (uint256 p = 0; p < totalPools; ++p) {
            address pool = $.knownPools.at(p);
            for (uint256 d = 0; d < totalDomains; ++d) {
                for (uint256 pr = 0; pr < totalProviders; ++pr) {
                    if (isRouteAllowed(pool, Domain(d), Provider(pr))) {
                        pools[resultLength] = pool;
                        domains[resultLength] = Domain(d);
                        providers[resultLength] = Provider(pr);
                        poolOnlySupportsToken[resultLength] = $.poolOnlySupportsToken[pool];
                        ++resultLength;
                    }
                }
            }
        }
        assembly ("memory-safe") {
            mstore(pools, resultLength)
            mstore(domains, resultLength)
            mstore(providers, resultLength)
            mstore(poolOnlySupportsToken, resultLength)
        }
        return (pools, domains, providers, poolOnlySupportsToken);
    }

    function _toIndex(Domain domain, Provider provider) internal pure returns (uint256) {
        return (uint256(domain) << 8) + uint256(provider);
    }

    function isRouteAllowed(address pool, Domain domain, Provider provider) public view returns (bool) {
        // As long as we deploy the Repayer contract on the same address on every supported domain this will work.
        // If we are to ever deploy it to new address, we will need to change this logic.
        if (pool == address(this)) {
            return true;
        }
        return _getStorage().allowedRoutes[pool].get(_toIndex(domain, provider));
    }

    function outputTokenData(
        address inputToken,
        Domain destinationDomain,
        bytes32 outputToken
    ) external view returns (bool isAllowed, int8 localDecimalsGreaterBy) {
        InputOutputTokenData storage inputOutputTokenData = _getStorage().inputOutputTokens[inputToken][outputToken];
        isAllowed = inputOutputTokenData.destinationDomains.get(uint256(destinationDomain));
        localDecimalsGreaterBy = inputOutputTokenData.localDecimalsGreaterBy[destinationDomain];
        return (isAllowed, localDecimalsGreaterBy);
    }

    function _getStorage() private pure returns (RepayerStorage storage $) {
        assembly {
            $.slot := STORAGE_LOCATION
        }
    }
}

contracts/utils/AcrossAdapter.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {V3SpokePoolInterface} from ".././interfaces/IAcross.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {AdapterHelper, InputOutputTokenData} from "./AdapterHelper.sol";

abstract contract AcrossAdapter is AdapterHelper {
    using SafeERC20 for IERC20;

    V3SpokePoolInterface immutable public ACROSS_SPOKE_POOL;

    constructor(
        address acrossSpokePool
    ) {
        // No check for address(0) to allow deployment on chains where SpokePool is not available
        ACROSS_SPOKE_POOL = V3SpokePoolInterface(acrossSpokePool);
    }

    function initiateTransferAcross(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        bytes calldata extraData,
        mapping(bytes32 => InputOutputTokenData) storage outputTokens
    ) internal notPayable {
        require(address(ACROSS_SPOKE_POOL) != address(0), ZeroAddress());
        token.forceApprove(address(ACROSS_SPOKE_POOL), amount);
        (
            address outputToken,
            uint256 outputAmount,
            address exclusiveRelayer,
            uint32 quoteTimestamp, // Validated in the spoke pool
            uint32 fillDeadline, // Validated in the spoke pool
            uint32 exclusivityDeadline
        ) = abi.decode(extraData, (address, uint256, address, uint32, uint32, uint32));
        _validateOutputAmount(amount, outputAmount, outputToken, destinationDomain, outputTokens);
        _validateOutputToken(outputToken, destinationDomain, outputTokens);
        ACROSS_SPOKE_POOL.depositV3(
            address(this),
            destinationPool,
            address(token),
            outputToken,
            amount,
            outputAmount,
            domainChainId(destinationDomain),
            exclusiveRelayer,
            quoteTimestamp,
            fillDeadline,
            exclusivityDeadline,
            "" // message
        );
    }
}

contracts/utils/AdapterHelper.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {BitMaps} from "@openzeppelin/contracts/utils/structs/BitMaps.sol";
import {IRoute} from "../interfaces/IRoute.sol";

struct InputOutputTokenData {
    BitMaps.BitMap destinationDomains;
    mapping(IRoute.Domain destinationDomain => int8) localDecimalsGreaterBy;
}

abstract contract AdapterHelper is IRoute {
    using BitMaps for BitMaps.BitMap;

    error SlippageTooHigh();
    error NotPayable();
    error InvalidOutputToken();
    error InvalidToken();
    /// @notice Raised by adapters that can only bridge to their own address on the destination
    /// chain, when the caller specifies a different destination pool.
    error InvalidDestinationPool();

    modifier notPayable() {
        require(msg.value == 0, NotPayable());
        _;
    }

    function domainChainId(Domain destinationDomain) public pure virtual returns (uint32) {
        if (destinationDomain == Domain.ETHEREUM) {
            return 1;
        } else
        if (destinationDomain == Domain.AVALANCHE) {
            return 43114;
        } else
        if (destinationDomain == Domain.OP_MAINNET) {
            return 10;
        } else
        if (destinationDomain == Domain.ARBITRUM_ONE) {
            return 42161;
        } else
        if (destinationDomain == Domain.BASE) {
            return 8453;
        } else
        if (destinationDomain == Domain.POLYGON_MAINNET) {
            return 137;
        } else
        if (destinationDomain == Domain.UNICHAIN) {
            return 130;
        } else
        if (destinationDomain == Domain.BSC) {
            return 56;
        } else
        if (destinationDomain == Domain.LINEA) {
            return 59144;
        } else
        if (destinationDomain == Domain.GNOSIS_CHAIN) {
            return 100;
        } else {
            revert UnsupportedDomain();
        }
    }

    function _addressToBytes32(address addr) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(addr)));
    }

    function _validateOutputToken(
        bytes32 outputToken,
        Domain destinationDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal view {
        require(outputTokens[outputToken].destinationDomains.get(uint256(destinationDomain)), InvalidOutputToken());
    }

    function _validateOutputToken(
        address outputToken,
        Domain destinationDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal view {
        _validateOutputToken(_addressToBytes32(outputToken), destinationDomain, outputTokens);
    }

    function _outputAmountToLocal(
        uint256 outputAmount,
        bytes32 outputToken,
        Domain destinationDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal view returns (uint256) {
        int8 localDecimalsGreaterBy = outputTokens[outputToken].localDecimalsGreaterBy[destinationDomain];
        if (localDecimalsGreaterBy == 0) {
            return outputAmount;
        }
        if (localDecimalsGreaterBy > 0) {
            return outputAmount * 10 ** uint256(uint8(localDecimalsGreaterBy));
        }
        return outputAmount / 10 ** uint256(uint8(-localDecimalsGreaterBy));
    }

    function _validateOutputAmount(
        uint256 inputAmount,
        uint256 outputAmount
    ) internal pure {
        require(outputAmount >= (inputAmount * 9980 / 10000), SlippageTooHigh());
    }

    function _validateOutputAmount(
        uint256 inputAmount,
        uint256 outputAmount,
        bytes32 outputToken,
        Domain destinationDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal view {
        _validateOutputAmount(
            inputAmount,
            _outputAmountToLocal(outputAmount, outputToken, destinationDomain, outputTokens)
        );
    }

    function _validateOutputAmount(
        uint256 inputAmount,
        uint256 outputAmount,
        address outputToken,
        Domain destinationDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal view {
        _validateOutputAmount(
            inputAmount,
            outputAmount,
            _addressToBytes32(outputToken),
            destinationDomain,
            outputTokens
        );
    }
}

contracts/utils/ArbitrumGatewayAdapter.s.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IArbitrumGatewayRouter} from ".././interfaces/IArbitrumGatewayRouter.sol";
import {AdapterHelper, InputOutputTokenData} from "./AdapterHelper.sol";

abstract contract ArbitrumGatewayAdapter is AdapterHelper {
    using SafeERC20 for IERC20;

    IArbitrumGatewayRouter immutable public ARBITRUM_GATEWAY_ROUTER;

    event ArbitrumERC20TransferInitiated(bytes gatewayData);

    constructor(
        address arbitrumGatewayRouter
    ) {
        // No check for address(0) to allow deployment on chains where Arbitrum Bridge is not available
        ARBITRUM_GATEWAY_ROUTER = IArbitrumGatewayRouter(arbitrumGatewayRouter);
    }

    function initiateTransferArbitrum(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        bytes calldata extraData,
        Domain localDomain,
        mapping(bytes32 => InputOutputTokenData) storage outputTokens
    ) internal {
        // We are only interested in fast L1->L2 bridging, because the reverse is slow.
        require(localDomain == Domain.ETHEREUM, UnsupportedDomain());
        require(destinationDomain == Domain.ARBITRUM_ONE, UnsupportedDomain());
        IArbitrumGatewayRouter router = ARBITRUM_GATEWAY_ROUTER;
        require(address(router) != address(0), ZeroAddress());
        (address outputToken, uint256 maxGas, uint256 gasPriceBid, bytes memory data) =
            abi.decode(extraData, (address, uint256, uint256, bytes));

        _validateOutputToken(outputToken, destinationDomain, outputTokens);
        // Get output token from the gateway
        address gatewayOutputToken = router.calculateL2TokenAddress(address(token));
        // Check that output tokens match
        require(gatewayOutputToken == outputToken, InvalidOutputToken());
        address gateway = router.getGateway(address(token));
        token.forceApprove(gateway, amount);
        bytes memory gatewayData = router.outboundTransfer{value: msg.value}(
            address(token),
            destinationPool,
            amount,
            maxGas,
            gasPriceBid,
            data
        );
        emit ArbitrumERC20TransferInitiated(gatewayData);
    }
}

contracts/utils/CCTPV2Adapter.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {ICCTPV2TokenMessenger, ICCTPV2MessageTransmitter} from "../interfaces/ICCTPV2.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {AdapterHelper} from "./AdapterHelper.sol";

/// @notice The child contract has to be deployed to the same address across chains, otherwise
/// processTransferCCTPV2() won't work, as the same address has to call receiveMessage().
/// Only supports CCTP V2 standard transfer (maxFee = 0, minFinalityThreshold = 2000).
abstract contract CCTPV2Adapter is AdapterHelper {
    using SafeERC20 for IERC20;

    IERC20 immutable public CCTP_V2_ONLY_SUPPORTED_TOKEN;
    ICCTPV2TokenMessenger immutable public CCTP_V2_TOKEN_MESSENGER;
    ICCTPV2MessageTransmitter immutable public CCTP_V2_MESSAGE_TRANSMITTER;

    constructor(
        IERC20 onlySupportedToken,
        address cctpV2TokenMessenger,
        address cctpV2MessageTransmitter
    ) {
        // No check for address(0) to allow deployment on chains where CCTP V2 is not available
        CCTP_V2_ONLY_SUPPORTED_TOKEN = onlySupportedToken;
        CCTP_V2_TOKEN_MESSENGER = ICCTPV2TokenMessenger(cctpV2TokenMessenger);
        CCTP_V2_MESSAGE_TRANSMITTER = ICCTPV2MessageTransmitter(cctpV2MessageTransmitter);
    }

    function initiateTransferCCTPV2(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain
    ) internal notPayable {
        require(token == CCTP_V2_ONLY_SUPPORTED_TOKEN, InvalidToken());
        require(address(CCTP_V2_TOKEN_MESSENGER) != address(0), ZeroAddress());
        token.forceApprove(address(CCTP_V2_TOKEN_MESSENGER), amount);
        // Standard transfer: maxFee = 0, minFinalityThreshold = 2000 (hard finality, no fast-transfer fee).
        // See https://github.com/circlefin/evm-cctp-contracts/blob/master/src/v2/FinalityThresholds.sol
        CCTP_V2_TOKEN_MESSENGER.depositForBurn(
            amount,
            domainCCTP(destinationDomain),
            _addressToBytes32(destinationPool),
            address(token),
            _addressToBytes32(address(this)),
            0,
            2000
        );
    }

    function processTransferCCTPV2(
        address destinationPool,
        bytes calldata extraData
    ) internal returns (IERC20, uint256) {
        require(address(CCTP_V2_MESSAGE_TRANSMITTER) != address(0), ZeroAddress());
        return _processTransferCCTP(address(CCTP_V2_MESSAGE_TRANSMITTER), destinationPool, extraData);
    }

    function _processTransferCCTP(
        address messageTransmitter,
        address destinationPool,
        bytes calldata extraData
    ) internal returns (IERC20, uint256) {
        uint256 balanceBefore = CCTP_V2_ONLY_SUPPORTED_TOKEN.balanceOf(destinationPool);
        (bytes memory message, bytes memory attestation) = abi.decode(extraData, (bytes, bytes));
        bool success = ICCTPV2MessageTransmitter(messageTransmitter).receiveMessage(message, attestation);
        require(success, ProcessFailed());
        uint256 balanceAfter = CCTP_V2_ONLY_SUPPORTED_TOKEN.balanceOf(destinationPool);
        require(balanceAfter > balanceBefore, ProcessFailed());
        unchecked {
            return (CCTP_V2_ONLY_SUPPORTED_TOKEN, balanceAfter - balanceBefore);
        }
    }

    function domainCCTP(Domain destinationDomain) public pure virtual returns (uint32) {
        if (destinationDomain == Domain.ETHEREUM) {
            return 0;
        } else
        if (destinationDomain == Domain.AVALANCHE) {
            return 1;
        } else
        if (destinationDomain == Domain.OP_MAINNET) {
            return 2;
        } else
        if (destinationDomain == Domain.ARBITRUM_ONE) {
            return 3;
        } else
        if (destinationDomain == Domain.BASE) {
            return 6;
        } else
        if (destinationDomain == Domain.POLYGON_MAINNET) {
            return 7;
        } else
        if (destinationDomain == Domain.UNICHAIN) {
            return 10;
        } else
        if (destinationDomain == Domain.LINEA) {
            return 11;
        } else
        if (destinationDomain == Domain.WORLD_CHAIN) {
            return 14;
        } else
        if (destinationDomain == Domain.HYPER_EVM) {
            return 19;
        } else
        if (destinationDomain == Domain.INK) {
            return 21;
        } else {
            revert UnsupportedDomain();
        }
    }
}

