// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

library ERC7201Helper {
    error InvalidStorageSlot(string namespace);

    function validateStorageLocation(bytes32 actual, string memory namespace) internal pure {
        bytes32 expected = getStorageLocation(bytes(namespace));
        require(actual == expected, InvalidStorageSlot(namespace));
    }

    function getStorageLocation(bytes memory namespace) internal pure returns(bytes32) {
        return keccak256(abi.encode(uint256(keccak256(namespace)) - 1)) & ~bytes32(uint256(0xff));
    }
}

contracts/utils/GnosisOmnibridgeAdapter..content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IGnosisOmnibridge, IGnosisAMB, IUSDCTransmuter} from ".././interfaces/IGnosisOmnibridge.sol";
import {AdapterHelper} from "./AdapterHelper.sol";

abstract contract GnosisOmnibridgeAdapter is AdapterHelper {
    using SafeERC20 for IERC20;

    /// @notice Omnibridge mediator on the local chain (Ethereum or Gnosis Chain).
    IGnosisOmnibridge immutable public OMNIBRIDGE;
    /// @notice On Gnosis it is USDCe token (Circle's Bridged USDC Standard)
    /// Must be swapped to GNOSIS_USDCXDAI before bridging via Omnibridge from Gnosis.
    /// @notice On Ethereum it is USDC token.
    /// Must be bridged to self to swap GNOSIS_USDCXDAI -> USDCe on Gnosis.
    IERC20 immutable public LOCAL_USDC;
    /// @notice USDC token on Gnosis Chain bridged from Ethereum via Omnibridge (USDCxDAI).
    IERC20 immutable public GNOSIS_USDCXDAI;
    /// @notice Swap contract that converts USDCe to USDCxDAI 1:1 on Gnosis Chain.
    IUSDCTransmuter immutable public GNOSIS_USDC_TRANSMUTER;
    /// @notice Ethereum AMB used to finalise Gnosis Chain → Ethereum transfers via executeSignatures.
    IGnosisAMB immutable public ETHEREUM_AMB;

    event GnosisOmnibridgeTransferInitiated(address indexed token, address indexed receiver, uint256 amount);

    error InsufficientBalance();

    constructor(
        Domain localDomain,
        address omnibridge,
        address localUSDC,
        address gnosisUsdcxdai,
        address gnosisUsdcTransmuter,
        address ethereumAmb
    ) {
        if (localDomain == Domain.ETHEREUM) {
            require(localUSDC != address(0), ZeroAddress());
            require(omnibridge != address(0), ZeroAddress());
            require(ethereumAmb != address(0), ZeroAddress());
            ETHEREUM_AMB = IGnosisAMB(ethereumAmb);
        } else
        if (localDomain == Domain.GNOSIS_CHAIN) {
            require(localUSDC != address(0), ZeroAddress());
            require(omnibridge != address(0), ZeroAddress());
            require(gnosisUsdcxdai != address(0), ZeroAddress());
            require(gnosisUsdcTransmuter != address(0), ZeroAddress());
            GNOSIS_USDCXDAI = IERC20(gnosisUsdcxdai);
            GNOSIS_USDC_TRANSMUTER = IUSDCTransmuter(gnosisUsdcTransmuter);
        } else {
            require(omnibridge == address(0), ZeroAddress());
            require(gnosisUsdcxdai == address(0), ZeroAddress());
            require(gnosisUsdcTransmuter == address(0), ZeroAddress());
            require(ethereumAmb == address(0), ZeroAddress());
        }
        LOCAL_USDC = IERC20(localUSDC);
        OMNIBRIDGE = IGnosisOmnibridge(omnibridge);
    }

    /// @notice Bridges ERC20 tokens between Ethereum and Gnosis Chain via the Omnibridge.
    /// Supports both directions:
    ///   - Ethereum → Gnosis Chain: relayTokens on the Ethereum mediator.
    ///   - Gnosis Chain → Ethereum: if token is USDCe, swaps it to USDCxDAI first,
    ///     then relayTokens on the Gnosis Chain mediator.
    function initiateTransferGnosisOmnibridge(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        Domain localDomain
    ) internal notPayable {
        require(address(OMNIBRIDGE) != address(0), ZeroAddress());
        if (localDomain == Domain.ETHEREUM) {
            require(destinationDomain == Domain.GNOSIS_CHAIN, UnsupportedDomain());
            if (address(token) == address(LOCAL_USDC)) {
                // Must bridge USDC to self to swap USDCxDAI on Gnosis through process().
                require(destinationPool == address(this), InvalidDestinationPool());
            }
        } else
        if (localDomain == Domain.GNOSIS_CHAIN) {
            require(destinationDomain == Domain.ETHEREUM, UnsupportedDomain());
            // USDCe cannot be bridged via Omnibridge; swap to USDCxDAI first.
            // Ethereum will receive USDC.
            if (address(token) == address(LOCAL_USDC)) {
                IUSDCTransmuter usdceSwap = GNOSIS_USDC_TRANSMUTER;
                token.forceApprove(address(usdceSwap), amount);
                usdceSwap.withdraw(amount);
                token = GNOSIS_USDCXDAI;
            }
        } else {
            // Unreachable due to constructor check.
            revert UnsupportedDomain();
        }
        token.forceApprove(address(OMNIBRIDGE), amount);
        OMNIBRIDGE.relayTokens(address(token), destinationPool, amount);
        emit GnosisOmnibridgeTransferInitiated(address(token), destinationPool, amount);
    }

    /// @notice Finalises a Gnosis Chain → Ethereum bridge transfer by submitting validator signatures
    /// to the Ethereum AMB. Must be called on Ethereum after the validators have signed the message.
    /// @param destinationPool The pool that will receive the bridged tokens.
    /// @param localDomain The domain of the local chain (Ethereum or Gnosis Chain).
    /// @param extraData ABI-encoded (address token, bytes message, bytes signatures).
    ///   token      - the ERC20 token expected to arrive at destinationPool.
    ///   message    - the bridge message from the Gnosis Chain bridge event.
    ///   signatures - the packed validator signatures collected on Gnosis Chain.
    /// @return token  The token that was received.
    /// @return amount The amount of tokens received by destinationPool.
    function processTransferGnosisOmnibridge(
        address destinationPool,
        Domain localDomain,
        bytes calldata extraData
    ) internal returns (IERC20 token, uint256 amount) {
        if (localDomain == Domain.ETHEREUM) {
            // No swap is needed on Ethereum.
            IGnosisAMB amb = ETHEREUM_AMB;

            bytes memory message;
            bytes memory signatures;
            (token, message, signatures) = abi.decode(extraData, (IERC20, bytes, bytes));

            uint256 balanceBefore = token.balanceOf(destinationPool);
            amb.executeSignatures(message, signatures);
            uint256 balanceAfter = token.balanceOf(destinationPool);

            require(balanceAfter > balanceBefore, ProcessFailed());
            amount = balanceAfter - balanceBefore;
        } else
        if (localDomain == Domain.GNOSIS_CHAIN) {
            // Only needed to process GNOSIS_USDCXDAI -> USDCe that arrive when USDC is sent from Ethereum.
            amount = abi.decode(extraData, (uint256));
            uint256 balance = GNOSIS_USDCXDAI.balanceOf(address(this));
            require(balance >= amount, InsufficientBalance());
            IUSDCTransmuter usdceSwap = GNOSIS_USDC_TRANSMUTER;
            GNOSIS_USDCXDAI.forceApprove(address(usdceSwap), balance);
            usdceSwap.deposit(balance);
            token = LOCAL_USDC;
        } else {
            // Unreachable if domain is correct, due to constructor check.
            revert UnsupportedDomain();
        }
        return (token, amount);
    }
}

contracts/utils/HelperLib.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

library HelperLib {
    error InvalidLength();

    function validatePositiveLength(uint256 a, uint256 b) internal pure returns (uint256) {
        require(a == b && a > 0, InvalidLength());
        return a; 
    }

    function balanceOfThis(IERC20 token) internal view returns (uint256) {
        return balanceOf(token, address(this));
    }

    function balanceOfThis(address token) internal view returns (uint256) {
        return balanceOfThis(IERC20(token));
    }

    function balanceOf(IERC20 token, address owner) internal view returns (uint256) {
        return token.balanceOf(owner);
    }
}

contracts/utils/LayerZeroHelper.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {AdapterHelper} from "./AdapterHelper.sol";

/// @notice Shared LayerZero endpoint ID mapping used by adapters that send messages via LayerZero v2.
abstract contract LayerZeroHelper is AdapterHelper {
    function layerZeroEndpointId(Domain destinationDomain) public pure virtual returns (uint32) {
        if (destinationDomain == Domain.ETHEREUM) {
            return 30101;
        } else
        if (destinationDomain == Domain.AVALANCHE) {
            return 30106;
        } else
        if (destinationDomain == Domain.OP_MAINNET) {
            return 30111;
        } else
        if (destinationDomain == Domain.ARBITRUM_ONE) {
            return 30110;
        } else
        if (destinationDomain == Domain.BASE) {
            return 30184;
        } else
        if (destinationDomain == Domain.POLYGON_MAINNET) {
            return 30109;
        } else
        if (destinationDomain == Domain.UNICHAIN) {
            return 30320;
        } else
        if (destinationDomain == Domain.BSC) {
            return 30102;
        } else
        if (destinationDomain == Domain.LINEA) {
            return 30183;
        } else
        if (destinationDomain == Domain.GNOSIS_CHAIN) {
            return 30145;
        } else
        if (destinationDomain == Domain.TEMPO) {
            return 30410;
        } else
        if (destinationDomain == Domain.STABLE) {
            return 30396;
        } else
        if (destinationDomain == Domain.TRON) {
            return 30420;
        } else {
            revert UnsupportedDomain();
        }
    }
}

contracts/utils/PolygonPosBridgeAdapter..content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IPolygonRootChainManager, IPolygonChildERC20} from ".././interfaces/IPolygonPosBridge.sol";
import {AdapterHelper, InputOutputTokenData} from "./AdapterHelper.sol";
import {HelperLib} from "./HelperLib.sol";

/// @notice Bridges tokens between Ethereum and Polygon over the Polygon PoS bridge.
/// Ethereum -> Polygon takes minutes, Polygon -> Ethereum takes 30 minutes to 3 hours,
/// because the burn has to be checkpointed before it can be exited.
/// @notice The child contract has to be deployed to the same address on Ethereum and Polygon,
/// otherwise processTransferPolygonPosBridge() won't work, as the PoS predicate always releases
/// the exited tokens to the address that burned the child token on Polygon.
abstract contract PolygonPosBridgeAdapter is AdapterHelper {
    using SafeERC20 for IERC20;

    /// @notice Polygon PoS RootChainManager on Ethereum. Zero on every other chain.
    IPolygonRootChainManager immutable public POLYGON_POS_ROOT_CHAIN_MANAGER;

    event PolygonPosDepositInitiated(address token, address receiver, uint256 amount);
    event PolygonPosWithdrawInitiated(address token, uint256 amount);

    constructor(
        address polygonPosRootChainManager
    ) {
        // No check for address(0) to allow deployment on chains where Polygon PoS Bridge is not available
        POLYGON_POS_ROOT_CHAIN_MANAGER = IPolygonRootChainManager(polygonPosRootChainManager);
    }

    /// @notice Bridges ERC20 tokens between Ethereum and Polygon via the PoS bridge.
    /// Supports both directions:
    ///   - Ethereum -> Polygon: depositFor on the RootChainManager, funds arrive at destinationPool.
    ///   - Polygon -> Ethereum: withdraw on the child token, funds arrive at this contract on
    ///     Ethereum once processTransferPolygonPosBridge() proves the burn.
    /// @param extraData ABI-encoded (address outputToken), the token expected on the destination domain.
    function initiateTransferPolygonPosBridge(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        bytes calldata extraData,
        Domain localDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal notPayable {
        address outputToken = abi.decode(extraData, (address));
        _validateOutputToken(outputToken, destinationDomain, outputTokens);
        if (localDomain == Domain.ETHEREUM) {
            require(destinationDomain == Domain.POLYGON_MAINNET, UnsupportedDomain());
            IPolygonRootChainManager manager = POLYGON_POS_ROOT_CHAIN_MANAGER;
            require(address(manager) != address(0), ZeroAddress());
            // The bridge mints a fixed child token per root token, check that it is the expected one.
            require(manager.rootToChildToken(address(token)) == outputToken, InvalidOutputToken());
            // Deposits are pulled by the predicate registered for the token type, not by the manager.
            address predicate = manager.typeToPredicate(manager.tokenToType(address(token)));
            require(predicate != address(0), ZeroAddress());
            token.forceApprove(predicate, amount);
            manager.depositFor(destinationPool, address(token), abi.encode(amount));
            emit PolygonPosDepositInitiated(address(token), destinationPool, amount);
        } else
        if (localDomain == Domain.POLYGON_MAINNET) {
            require(destinationDomain == Domain.ETHEREUM, UnsupportedDomain());
            // The exit releases the tokens to whoever burned them on Polygon, so they have to
            // come back to this contract and be forwarded by process().
            require(destinationPool == address(this), InvalidDestinationPool());
            IPolygonChildERC20(address(token)).withdraw(amount);
            emit PolygonPosWithdrawInitiated(address(token), amount);
        } else {
            revert UnsupportedDomain();
        }
    }

    /// @notice Finalises a Polygon -> Ethereum transfer by proving the burn to the RootChainManager.
    /// Must be called on Ethereum after the burn has been checkpointed.
    /// @param extraData ABI-encoded (IERC20 token, bytes burnProof).
    ///   token     - the Ethereum token expected to arrive at this contract.
    ///   burnProof - the RLP encoded proof of the burn transaction on Polygon.
    /// @return token  The token that was received.
    /// @return amount The amount of tokens received by this contract.
    function processTransferPolygonPosBridge(
        bytes calldata extraData
    ) internal returns (IERC20 token, uint256 amount) {
        IPolygonRootChainManager manager = POLYGON_POS_ROOT_CHAIN_MANAGER;
        require(address(manager) != address(0), ZeroAddress());

        bytes memory burnProof;
        (token, burnProof) = abi.decode(extraData, (IERC20, bytes));

        uint256 balanceBefore = HelperLib.balanceOfThis(token);
        manager.exit(burnProof);
        uint256 balanceAfter = HelperLib.balanceOfThis(token);

        require(balanceAfter > balanceBefore, ProcessFailed());
        unchecked {
            return (token, balanceAfter - balanceBefore);
        }
    }
}

contracts/utils/StargateAdapter.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {
    IStargate,
    SendParam,
    OFTReceipt,
    MessagingFee,
    MessagingReceipt,
    Ticket,
    IStargateTreasurer
} from ".././interfaces/IStargate.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {LayerZeroHelper} from "./LayerZeroHelper.sol";

abstract contract StargateAdapter is LayerZeroHelper {
    using SafeERC20 for IERC20;

    IStargateTreasurer immutable public STARGATE_TREASURER;

    error EtherTransferFailed();
    error PoolInvalid();

    event StargateTransfer(
        MessagingReceipt msgReceipt,
        OFTReceipt oftReceipt,
        Ticket ticket
    );

    constructor(
        address stargateTreasurer
    ) {
        // No check for address(0) to allow deployment on chains where Stargate Treasurer is not available
        STARGATE_TREASURER = IStargateTreasurer(stargateTreasurer);
    }

    function initiateTransferStargate(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        bytes calldata extraData,
        address caller
    ) internal {
        (address stargateAddress, uint256 minAmountOut) = abi.decode(extraData, (address, uint256));
        _validateOutputAmount(amount, minAmountOut);
        require(STARGATE_TREASURER.stargates(stargateAddress), PoolInvalid());
        IStargate stargate = IStargate(stargateAddress);
        require(address(token) == stargate.token(), PoolInvalid());

        token.forceApprove(address(stargate), amount);

        uint32 dstEid = layerZeroEndpointId(destinationDomain);

        SendParam memory sendParam = SendParam({
            dstEid: dstEid,
            to: _addressToBytes32(destinationPool),
            amountLD: amount,
            minAmountLD: minAmountOut,
            extraOptions: new bytes(0),
            composeMsg: new bytes(0),
            oftCmd: new bytes(1)
        });

        // TODO: Add support for chains without a native token, like Tempo.
        // The caller is responsible for estimating and providing the correct messaging fee.
        MessagingFee memory messagingFee = MessagingFee(msg.value, 0);

        (
            MessagingReceipt memory msgReceipt,
            OFTReceipt memory oftReceipt,
            Ticket memory ticket
        ) = stargate.sendToken{ value: msg.value }(sendParam, messagingFee, caller);

        emit StargateTransfer(msgReceipt, oftReceipt, ticket);
    }
}

contracts/utils/SuperchainStandardBridge.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ISuperchainStandardBridge} from ".././interfaces/ISuperchainStandardBridge.sol";
import {IWrappedNativeToken} from ".././interfaces/IWrappedNativeToken.sol";
import {AdapterHelper, InputOutputTokenData} from "./AdapterHelper.sol";

abstract contract SuperchainStandardBridgeAdapter is AdapterHelper {
    using SafeERC20 for IERC20;

    ISuperchainStandardBridge immutable public OPTIMISM_STANDARD_BRIDGE;
    ISuperchainStandardBridge immutable public BASE_STANDARD_BRIDGE;
    IWrappedNativeToken immutable private WRAPPED_NATIVE_TOKEN;
    IERC20 immutable private ASSET_TOKEN;

    constructor(
        address optimismStandardBridge,
        address baseStandardBridge,
        address wrappedNativeToken,
        address assetToken
    ) {
        // No check for address(0) to allow deployment on chains where Standard Bridge is not available
        OPTIMISM_STANDARD_BRIDGE = ISuperchainStandardBridge(optimismStandardBridge);
        BASE_STANDARD_BRIDGE = ISuperchainStandardBridge(baseStandardBridge);
        WRAPPED_NATIVE_TOKEN = IWrappedNativeToken(wrappedNativeToken);
        ASSET_TOKEN = IERC20(assetToken);
    }

    function initiateTransferSuperchainStandardBridge(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        bytes calldata extraData,
        Domain localDomain,
        mapping(bytes32 outputToken => InputOutputTokenData) storage outputTokens
    ) internal notPayable {
        // We are only interested in fast L1->L2 bridging, because the reverse is slow.
        require(localDomain == Domain.ETHEREUM, UnsupportedDomain());
        require(token != ASSET_TOKEN, InvalidToken());
        ISuperchainStandardBridge standardBridge;
        if (destinationDomain == Domain.OP_MAINNET) {
            standardBridge = OPTIMISM_STANDARD_BRIDGE;
        } else if (destinationDomain == Domain.BASE) {
            standardBridge = BASE_STANDARD_BRIDGE;
        } else {
            revert UnsupportedDomain();
        }
        require(address(standardBridge) != address(0), ZeroAddress());
        // Notice: In case of minGasLimit being too low, the message could be retried on the destination chain.
        (address outputToken, uint32 minGasLimit, bytes memory message) =
            abi.decode(extraData, (address, uint32, bytes));
        if (token == WRAPPED_NATIVE_TOKEN) {
            require(outputToken == address(0), InvalidOutputToken());
            WRAPPED_NATIVE_TOKEN.withdraw(amount);
            standardBridge.bridgeETHTo{value: amount}(destinationPool, minGasLimit, message);
            return;
        }

        _validateOutputToken(outputToken, destinationDomain, outputTokens);
        token.forceApprove(address(standardBridge), amount);
        standardBridge.bridgeERC20To(
            address(token),
            outputToken,
            destinationPool,
            amount,
            minGasLimit,
            message
        );
    }
}

contracts/utils/USDT0Adapter.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.26;

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {SendParam, MessagingFee} from ".././interfaces/ILayerZero.sol";
import {IOFT} from ".././interfaces/IOFT.sol";
import {LayerZeroHelper} from "./LayerZeroHelper.sol";

abstract contract USDT0Adapter is LayerZeroHelper {
    using SafeERC20 for IERC20;

    /// @notice The USDT0 OFT contract on the local chain.
    /// On Ethereum this is an OAdapterUpgradeable (locks/unlocks native USDT via transferFrom).
    /// On all other chains it is an OUpgradeable (burns/mints USDT0 directly — no approval needed).
    IOFT immutable public USDT0_OFT;
    address immutable public USDT0_FEE_NATIVE_TOKEN;

    event USDT0Transfer(address token, address receiver, uint32 dstEid, uint256 amount);

    error InvalidNativeToken();
    error InvalidExtraData();

    constructor(address usdt0Oft, address usdt0FeeNativeToken) {
        // No check for address(0): allows deployment on chains where USDT0 is not available.
        USDT0_OFT = IOFT(usdt0Oft);
        if (usdt0FeeNativeToken != address(0)) {
            require(usdt0FeeNativeToken == USDT0_OFT.nativeToken(), InvalidNativeToken());
        }
        USDT0_FEE_NATIVE_TOKEN = usdt0FeeNativeToken;
    }

    /// @notice Initiates a cross-chain transfer of USDT0 via LayerZero.
    /// @dev The caller must supply sufficient native currency (msg.value) to cover the LayerZero
    /// messaging fee. Any excess is refunded to `caller` by the OFT contract.
    /// amountLD and minAmountLD are set equal — no slippage is accepted.
    /// @param token The ERC-20 token to bridge. Must match USDT0_OFT.token().
    /// @param amount The amount to send in local decimals (6 for USDT0).
    /// @param destinationPool The recipient address on the destination chain.
    /// @param destinationDomain The destination domain.
    /// @param caller The address that initiated the call; used as the LayerZero fee refund address.
    function initiateTransferUSDT0(
        IERC20 token,
        uint256 amount,
        address destinationPool,
        Domain destinationDomain,
        bytes calldata extraData,
        address caller
    ) internal {
        IOFT oft = USDT0_OFT;
        require(address(oft) != address(0), ZeroAddress());
        require(address(token) == oft.token(), InvalidToken());
        require(extraData.length >= 32, InvalidExtraData());
        uint256 minAmountLD = abi.decode(extraData[0:32], (uint256));
        _validateOutputAmount(amount, minAmountLD);

        if (oft.approvalRequired()) {
            token.forceApprove(address(oft), amount);
        }

        uint32 dstEid = layerZeroEndpointId(destinationDomain);

        SendParam memory sendParam = SendParam({
            dstEid: dstEid,
            to: _addressToBytes32(destinationPool),
            amountLD: amount,
            minAmountLD: minAmountLD,
            extraOptions: new bytes(0),
            composeMsg: new bytes(0),
            oftCmd: new bytes(0)
        });

        MessagingFee memory fee;
        if (USDT0_FEE_NATIVE_TOKEN == address(0)) {
            require(extraData.length == 32, InvalidExtraData());
            fee.nativeFee = msg.value;
        } else {
            require(msg.value == 0, NotPayable());
            require(extraData.length == 64, InvalidExtraData());
            fee.nativeFee = abi.decode(extraData[32:64], (uint256));
            IERC20(USDT0_FEE_NATIVE_TOKEN).safeTransferFrom(caller, address(this), fee.nativeFee);
            IERC20(USDT0_FEE_NATIVE_TOKEN).forceApprove(address(oft), fee.nativeFee);
        }
        // solhint-disable-next-line check-send-result
        oft.send{value: msg.value}(sendParam, fee, caller);

        emit USDT0Transfer(address(token), destinationPool, dstEid, amount);
    }
}
